const h128 = (str) => {
  const seeds = [0x811c9dc5, 0x9e3779b1, 0x85ebca6b, 0xc2b2ae35];
  let o = '';
  for (const s0 of seeds) {
    let h = s0 >>> 0;
    for (let i = 0; i < str.length; i++) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619) >>> 0;
      h = (h ^ (h >>> 15)) >>> 0;
    }
    o += ('00000000' + h.toString(16)).slice(-8);
  }
  return o;
};
const toUuid = (h) => h.slice(0, 8) + '-' + h.slice(8, 12) + '-4' + h.slice(13, 16) + '-8' + h.slice(17, 20) + '-' + h.slice(20, 32);

const cfg = $('Config').first().json.cfg;
const e = $input.first().json;
const p = (e.payload && typeof e.payload === 'object') ? e.payload : {};
const base = { request_id: e.request_id };
const bad = (msg) => [{ json: { ...base, valid: false, error: msg, http_status: 400 } }];

let q = typeof p.question === 'string' ? p.question : '';
q = q.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').replace(/\s+/g, ' ').trim();
if (!q) return bad('question is required');
if (q.length > cfg.max_question_chars) return bad('question is too long (max ' + cfg.max_question_chars + ' characters)');

let session = typeof p.session_id === 'string' ? p.session_id.trim() : '';
if (!/^[A-Za-z0-9_-]{8,64}$/.test(session)) session = 'anon-' + h128(e.request_id).slice(0, 16);
const ip = e.client_ip || '';
const client_key = h128(ip ? 'ip:' + ip : 'sess:' + session);
const memory_session_id = h128(client_key + '|session:' + session);

// ---- secrets: never sent to the LLM, never stored, never logged in clear text
let masked = q;
const secrets = [];
const SEED_CTX = /(seed|mnemonic|recovery phrase|secret phrase|backup phrase|сид[- ]?фраз|мнемоник|секретн\S* фраз|фраз\S* восстановлен|frase semilla|frase secreta)/i;
const SEED_RUN = /(?:\b[a-z]{3,8}\b[\s,]+){11,23}\b[a-z]{3,8}\b/gi;
const KEY_CTX = /(private key|priv key|secret key|секретный ключ|приватн\S* ключ|clave privada|clave secreta)/i;
const HEX64 = /\b(?:0x)?[a-f0-9]{64}\b/gi;
const WIF = /\b[5KL][1-9A-HJ-NP-Za-km-z]{50,51}\b/g;
const JWT = /\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g;
const APIKEY = /\b(?:sk|pk|rk)[-_][A-Za-z0-9_-]{16,}\b/g;
const PASSWD = /(?:password|passwd|пароль|contraseña)\s*(?:is|es|:|=)\s*(?=\S*[\d!@#$%^&*])\S{6,}/gi;
if (SEED_CTX.test(q) && q.search(SEED_RUN) >= 0) { secrets.push('seed_phrase'); masked = masked.replace(SEED_RUN, '[REDACTED]'); }
if (KEY_CTX.test(q) && q.search(HEX64) >= 0) { secrets.push('private_key'); masked = masked.replace(HEX64, '[REDACTED]'); }
if (q.search(WIF) >= 0) { secrets.push('private_key'); masked = masked.replace(WIF, '[REDACTED]'); }
if (q.search(JWT) >= 0) { secrets.push('token'); masked = masked.replace(JWT, '[REDACTED]'); }
if (q.search(APIKEY) >= 0) { secrets.push('api_key'); masked = masked.replace(APIKEY, '[REDACTED]'); }
if (q.search(PASSWD) >= 0) { secrets.push('password'); masked = masked.replace(PASSWD, '[REDACTED]'); }
const secret_detected = secrets.length > 0;

const INJ = /(ignore\s+(all\s+|any\s+)?(previous|prior|above)\s+(instructions|rules)|disregard\s+(all\s+)?(previous|prior)|reveal\s+(your\s+)?system\s+prompt|you\s+are\s+now\s+|игнорир\S*\s+(все\s+|предыдущ\S*\s+)?(инструкц|правил)|забудь\s+(все\s+)?инструкц|ignora\s+(todas\s+)?las\s+instrucciones)/i;
const injection_suspected = INJ.test(q);

const lang = /[а-яё]/i.test(q) ? 'ru' : (/[¿¡ñáéíóúü]/i.test(q) ? 'es' : 'en');
const hint = typeof p.lang === 'string' && cfg.languages.includes(p.lang.toLowerCase()) ? p.lang.toLowerCase() : lang;
const safeQ = q.replace(/[<>]/g, ' ');
const norm = safeQ.toLowerCase().replace(/[^\p{L}\p{N} ]/gu, '').replace(/\s+/g, ' ').trim();
const has_txid = /\b(?:0x)?[a-f0-9]{64}\b/i.test(q);

let early_exit = false, early_decision = '', early_reason = '';
if (secret_detected) { early_exit = true; early_decision = 'SECRET'; early_reason = 'secret_detected'; }
else if (injection_suspected) { early_exit = true; early_decision = 'NO_ANSWER'; early_reason = 'injection_suspected'; }

return [{ json: {
  ...base, valid: true, session_id: session, memory_session_id, client_key, lang: hint,
  question: secret_detected ? '' : safeQ,
  question_masked: masked.replace(/[<>]/g, ' ').slice(0, 500),
  question_hash: h128(norm),
  flags: { secret_detected, secret_types: [...new Set(secrets)], injection_suspected, has_txid },
  early_exit, early_decision, early_reason,
} }];

const b = $input.first().json;
const secret = b.early_decision === 'SECRET';
return [{ json: {
  decision: b.early_decision,
  reasons: [b.early_reason],
  answer: '', sources: [], used_sources: [], metrics: {}, http_status: 200,
  lang: b.lang,
  skip_log: secret,
} }];

const cfg = $('Config').first().json.cfg;
const b = $('Validate Ask').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.request_id);
const limited = rows.length >= cfg.rate_limit_per_minute;
if (limited) return [{ json: { ...b, rate_limited: true, decision: 'RATE_LIMITED', reasons: ['rate_limited'], answer: '', sources: [], metrics: {}, http_status: 429, skip_log: true, lang: b.lang } }];
return [{ json: { ...b, rate_limited: false } }];

const b = $('Evaluate Rate Limit').first().json;
const row = $input.all().map(i => i.json).find(r => r.request_id && r.answer);
if (!row) return [{ json: { ...b, cache_hit: false } }];
let sources = [];
try { sources = JSON.parse(row.sources || '[]'); } catch (e) { sources = []; }
return [{ json: {
  ...b, cache_hit: true, decision: 'ANSWER', answer: row.answer, sources,
  used_sources: sources.map(s => s.n), reasons: ['cache_hit'], standalone: 1,
  metrics: { groundedness: Number(row.groundedness) || 0, best_score: Number(row.best_score) || 0 },
  http_status: 200, lang: row.language || b.lang,
} }];

const extractJson = (t) => {
  if (!t) return null;
  const s = String(t).replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), z = s.lastIndexOf('}');
  if (a < 0 || z <= a) return null;
  try { return JSON.parse(s.slice(a, z + 1)); } catch (e) { return null; }
};
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, Number.isFinite(n) ? n : lo));

const cfg = $('Config').first().json.cfg;
const b = $('Check Cache').first().json;
const raw = $input.first().json;
const r = raw.error ? null : extractJson(raw.output);
const INTENTS = ['faq', 'account_specific', 'investment_advice', 'fraud_suspected', 'complaint', 'other'];
const router_failed = !r;
let intent = r && INTENTS.includes(r.intent) ? r.intent : 'faq';
const language = r && cfg.languages.includes(r.language) ? r.language : b.lang;
const standalone = r && r.standalone === true ? 1 : 0;
const search_query = r && typeof r.search_query === 'string' && r.search_query.trim() ? r.search_query.trim().slice(0, 300) : b.question;
let collections = (r && Array.isArray(r.collections) ? r.collections : []).filter(c => cfg.collections.includes(c));
if (!collections.length) collections = cfg.collections;
let urgency = r && ['low', 'medium', 'high'].includes(r.urgency) ? r.urgency : 'low';

// ---- deterministic rules (they can only make the outcome stricter)
const q = b.question.toLowerCase();
const RE_FRAUD = /(фишинг|мошенн|взлом|украл|скам|scam|phish|hacked|stolen|stole|fraud|estafa|hackead|robaron)/i;
const RE_ACCOUNT = /(мо[йяеи]\s+(вывод|перевод|депозит|транзакци|баланс|аккаунт|счет|счёт|заявк|ордер)|не\s+пришл[иао]|не\s+поступил|where\s+is\s+my|my\s+(withdrawal|deposit|transaction|balance|account|order|funds)|(hasn'?t|has\s+not)\s+arrived|mi\s+(retiro|dep[oó]sito|transacci[oó]n|saldo|cuenta|pedido)|no\s+ha\s+llegado)/i;
const RE_GENERIC = /(лимит|комисси|минимальн|как\s+(сделать|вывести|пополнить|пройти)|how\s+(do|to|can)|limit|fee|minimum|c[oó]mo|l[ií]mite|comisi)/i;
const RE_INVEST = /(стоит\s+ли\s+(покупать|продавать)|прогноз\s+(цены|курса)|куда\s+пойд[её]т|price\s+prediction|should\s+i\s+(buy|sell)|buy\s+or\s+sell|will\s+(btc|eth|bitcoin)\b.*\b(go|reach|hit)|vale\s+la\s+pena\s+comprar|predicci[oó]n\s+de\s+precio)/i;
if (RE_FRAUD.test(q)) { intent = 'fraud_suspected'; urgency = 'high'; }
else if (b.flags && b.flags.has_txid) intent = 'account_specific';
else if (RE_ACCOUNT.test(q) && !RE_GENERIC.test(q)) intent = 'account_specific';
else if (RE_INVEST.test(q) && intent === 'faq') intent = 'investment_advice';

const reasons = [];
if (router_failed) reasons.push('router_failed');
let route = 'SEARCH', decision = '';
if (['fraud_suspected', 'account_specific', 'complaint'].includes(intent)) { route = 'RULE_ESCALATE'; decision = 'ESCALATE'; reasons.push('intent_' + intent); }
else if (intent === 'investment_advice') { route = 'RULE_REFUSE'; decision = 'REFUSE_ADVICE'; reasons.push('intent_investment_advice'); }

const out = { ...b, intent, lang: language, standalone, search_query, collections, urgency, route, router_failed, reasons };
if (route !== 'SEARCH') Object.assign(out, { decision, answer: '', sources: [], metrics: {}, http_status: 200 });
return [{ json: out }];

const cfg = $('Config').first().json.cfg;
const s = $('Parse Router').first().json;
const r = $input.first().json;
const vec = r && Array.isArray(r.data) && r.data[0] ? r.data[0].embedding : null;
const ok = !r.error && Array.isArray(vec) && vec.length === cfg.embedding_dim;
return s.collections.map(c => ({ json: { collection: c, vector: ok ? vec : null } }));

const cfg = $('Config').first().json.cfg;
const s = $('Parse Router').first().json;
const colls = $('Prepare Searches').all().map(x => x.json.collection);
let failed = 0;
const hits = [];
$input.all().forEach((it, i) => {
  const r = it.json;
  if (r.error || !Array.isArray(r.result)) { failed++; return; }
  for (const h of r.result) {
    const p = h.payload || {};
    if (!p.text) continue;
    hits.push({ score: h.score, doc_id: p.doc_id, title: p.title, collection: p.collection || colls[i], text: String(p.text), chunk_index: p.chunk_index });
  }
});
const reasons = [...(s.reasons || [])];
if (colls.length > 0 && failed === colls.length) {
  reasons.push('search_failed');
  return [{ json: { ...s, reasons, enough_context: false, decision: 'ESCALATE', answer: '', sources: [], metrics: {}, http_status: 200 } }];
}
if (failed > 0) reasons.push('partial_search_failure');
hits.sort((a, b) => b.score - a.score);
const seen = new Set(), perDoc = {}, top = [];
for (const h of hits) {
  const key = h.doc_id + '#' + h.chunk_index;
  if (seen.has(key)) continue;
  perDoc[h.doc_id] = (perDoc[h.doc_id] || 0) + 1;
  if (perDoc[h.doc_id] > 2) continue;
  seen.add(key);
  top.push(h);
  if (top.length >= cfg.max_context_chunks) break;
}
const best = top.length ? top[0].score : 0;
const enough = top.length >= 1 && best >= cfg.min_best_score;
const sources = top.map((h, i) => ({ n: i + 1, doc_id: h.doc_id, title: h.title, collection: h.collection }));
const context = top.map((h, i) => '[' + (i + 1) + '] (' + h.title + ')\n' + h.text.slice(0, cfg.max_chunk_chars).replace(/<\//g, '< /')).join('\n\n');
const out = { ...s, reasons, enough_context: enough, context, sources, best_score: best, chunks_found: top.length };
if (!enough) { reasons.push('no_relevant_context'); Object.assign(out, { decision: 'NO_ANSWER', answer: '', sources: [], metrics: { best_score: best }, http_status: 200 }); }
return [{ json: out }];

const extractJson = (t) => {
  if (!t) return null;
  const s = String(t).replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), z = s.lastIndexOf('}');
  if (a < 0 || z <= a) return null;
  try { return JSON.parse(s.slice(a, z + 1)); } catch (e) { return null; }
};
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, Number.isFinite(n) ? n : lo));
const s = $('Merge Search Results').first().json;
const raw = $input.first().json;
const r = raw.error ? null : extractJson(raw.output);
const reasons = [...(s.reasons || [])];
const stop = (decision, reason) => [{ json: { ...s, answer_ok: false, decision, answer: '', sources: [], used_sources: [], metrics: { best_score: s.best_score }, reasons: [...reasons, reason], http_status: 200 } }];
if (!r || typeof r.answer !== 'string') return stop('ESCALATE', 'answer_failed');
const answer = r.answer
  .replace(/\[([^\]]+)\]\((?:https?:\/\/|www\.)[^)]*\)/gi, '$1')
  .replace(/(?:https?:\/\/|www\.)\S+/gi, '')
  .replace(/[<>]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 1200);
if (r.needs_human === true) return stop('ESCALATE', 'model_requested_human');
const cited = [...new Set([...answer.matchAll(/\[(\d+)\]/g)].map(m => Number(m[1])))];
const declared = [...new Set((Array.isArray(r.used_sources) ? r.used_sources : []).map(Number).filter(n => Number.isInteger(n)))];
if (!answer || cited.length === 0) return stop('NO_ANSWER', 'uncited_answer');
if (cited.some(n => n < 1 || n > s.sources.length)) return stop('NO_ANSWER', 'invalid_citation');
if (declared.length && (declared.length !== cited.length || declared.some(n => !cited.includes(n)))) return stop('NO_ANSWER', 'citation_mismatch');
return [{ json: { ...s, answer_ok: true, answer, used_sources: cited, answer_confidence: clamp(Number(r.confidence), 0, 1) } }];

const extractJson = (t) => {
  if (!t) return null;
  const s = String(t).replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), z = s.lastIndexOf('}');
  if (a < 0 || z <= a) return null;
  try { return JSON.parse(s.slice(a, z + 1)); } catch (e) { return null; }
};
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, Number.isFinite(n) ? n : lo));

const s = $('Parse Answer').first().json;
const raw = $input.first().json;
const r = raw.error ? null : extractJson(raw.output);
if (!r) return [{ json: { ...s, critic_failed: true, groundedness: 0, verdict: 'fail', policy_violations: [], unsupported_count: 0 } }];
const verdict = ['pass', 'revise', 'fail'].includes(r.verdict) ? r.verdict : 'fail';
const pv = (Array.isArray(r.policy_violations) ? r.policy_violations : []).map(x => String(x).slice(0, 60)).slice(0, 8);
return [{ json: { ...s, critic_failed: false, groundedness: clamp(Number(r.groundedness), 0, 1), verdict, policy_violations: pv, unsupported_count: Array.isArray(r.unsupported_claims) ? r.unsupported_claims.length : 0 } }];

const cfg = $('Config').first().json.cfg;
const s = $input.first().json;
const reasons = [...(s.reasons || [])];
const RISKY = /(guarantee|guaranteed|risk[- ]free|гарантир|без\s+риск|100\s*%\s*(profit|прибыл)|garantizad)/i;
let decision;
if (s.critic_failed) { decision = 'ESCALATE'; reasons.push('critic_failed'); }
else if (s.policy_violations.length > 0 || s.verdict === 'fail') { decision = 'ESCALATE'; reasons.push('policy_violation'); }
else if (RISKY.test(s.answer)) { decision = 'ESCALATE'; reasons.push('risky_phrase'); }
else if (s.answer_ok === true && Array.isArray(s.used_sources) && s.used_sources.length > 0 && Array.isArray(s.sources) && s.used_sources.every(n => Number.isInteger(n) && n >= 1 && n <= s.sources.length) && s.groundedness >= cfg.answer_min_groundedness && s.verdict === 'pass' && s.answer_confidence >= cfg.min_answer_confidence) decision = 'ANSWER';
else if (s.groundedness >= cfg.clarify_min_groundedness) { decision = 'CLARIFY'; reasons.push('partially_grounded'); }
else { decision = 'NO_ANSWER'; reasons.push('low_groundedness'); }
return [{ json: { ...s, decision, reasons, http_status: 200,
  metrics: { groundedness: s.groundedness, best_score: s.best_score, confidence: s.answer_confidence, violations: s.policy_violations } } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const cfg = $('Config').first().json.cfg;
const b = $('Validate Ask').first().json;
const s = $input.first().json;
const lang = ['ru', 'en', 'es'].includes(s.lang) ? s.lang : (b.lang || 'en');
const T = {
  ESCALATE: { ru: 'Ваш вопрос передан специалисту поддержки. Номер обращения: {id}. Укажите его при обращении в поддержку.', en: 'Your question has been passed to a support specialist. Reference number: {id}. Please quote it when contacting support.', es: 'Tu consulta se ha enviado a un especialista de soporte. Número de referencia: {id}. Indícalo al contactar con soporte.' },
  NO_ANSWER: { ru: 'Я не нашёл надёжного ответа в базе знаний. Попробуйте переформулировать вопрос или обратитесь в поддержку.', en: "I couldn't find a reliable answer in the knowledge base. Please rephrase your question or contact support.", es: 'No he encontrado una respuesta fiable en la base de conocimiento. Reformula la pregunta o contacta con soporte.' },
  CLARIFY: { ru: 'Уточните, пожалуйста, детали вопроса (монета, сеть, тип операции), чтобы я мог найти точный ответ.', en: 'Could you add more detail (coin, network, type of operation) so I can find the exact answer?', es: '¿Puedes añadir más detalles (moneda, red, tipo de operación) para encontrar la respuesta exacta?' },
  REFUSE_ADVICE: { ru: 'Я не даю инвестиционных советов и прогнозов цен. Могу рассказать о комиссиях, лимитах и правилах платформы.', en: 'I do not give investment advice or price predictions. I can help with fees, limits and platform rules.', es: 'No doy consejos de inversión ni predicciones de precio. Puedo ayudarte con comisiones, límites y normas de la plataforma.' },
  SECRET: { ru: 'Похоже, в сообщении есть секретные данные (пароль, ключ или seed-фраза). Никому их не передавайте: поддержка их не запрашивает. Сообщение не сохранено и не обработано. Если данные уже раскрыты, смените пароль и ключи и включите 2FA.', en: 'Your message seems to contain secret data (a password, key or seed phrase). Never share it: support will never ask for it. The message was neither stored nor processed. If it has been exposed, change your password and keys and enable 2FA.', es: 'Tu mensaje parece contener datos secretos (contraseña, clave o frase semilla). No los compartas: soporte nunca los pide. El mensaje no se ha guardado ni procesado. Si ya se han expuesto, cambia la contraseña y las claves y activa 2FA.' },
  RATE_LIMITED: { ru: 'Слишком много запросов. Подождите минуту и попробуйте снова.', en: 'Too many requests. Please wait a minute and try again.', es: 'Demasiadas solicitudes. Espera un minuto e inténtalo de nuevo.' },
};
const decision = s.decision || 'ESCALATE';
const reasons = s.reasons || [];
const used = s.used_sources || (s.sources || []).map(x => x.n);
const srcs = decision === 'ANSWER' ? (s.sources || []).filter(x => used.includes(x.n)).map(x => ({ title: x.title, doc_id: x.doc_id, collection: x.collection })) : [];
const answer = decision === 'ANSWER' ? s.answer : (T[decision] || T.ESCALATE)[lang].replace('{id}', b.request_id);
const response = { request_id: b.request_id, session_id: b.session_id, decision, answer, sources: srcs, language: lang };
const m = s.metrics || {};
const log = {
  request_id: b.request_id, session_id: b.session_id, client_key: b.client_key, ts: Date.now(),
  question_hash: b.question_hash, question_masked: b.question_masked, decision,
  answer: decision === 'ANSWER' ? s.answer : '',
  sources: JSON.stringify(decision === 'ANSWER' ? (s.sources || []).filter(x => used.includes(x.n)) : []),
  language: lang, standalone: s.standalone ? 1 : 0,
  groundedness: Number(m.groundedness) || 0, best_score: Number(m.best_score) || 0,
  reasons: reasons.join(','), cache_hit: s.cache_hit ? 1 : 0,
};
const SYSTEM = ['search_failed', 'router_failed', 'answer_failed', 'critic_failed', 'secret_detected'];
const sysReason = reasons.find(r => SYSTEM.includes(r));
let system_alert = null;
if (sysReason) system_alert = { key: 'qa:' + sysReason, text: ':warning: *KB assistant* `' + esc(sysReason) + '` (request `' + esc(b.request_id) + '`)' + (sysReason === 'secret_detected' ? ' - a user pasted secret data; content was NOT stored' : '') };
const escalate = decision === 'ESCALATE';
const slack_escalation_text = escalate
  ? ':sos: *KB escalation* `' + esc(b.request_id) + '`\n*Intent:* ' + esc(s.intent || 'n/a') + '  *Urgency:* ' + esc(s.urgency || 'n/a') + '  *Lang:* ' + esc(lang) +
    '\n*Reasons:* ' + esc(reasons.join(', ') || 'n/a') + '\n*Question:* ' + esc(b.question_masked.slice(0, 300)) + '\n*Session:* `' + esc(b.session_id) + '`'
  : '';
return [{ json: {
  decision, http_status: s.http_status || 200, response, log, should_log: !s.skip_log,
  has_system_alert: !!system_alert, system_alert, escalate_notice: escalate, slack_escalation_text,
} }];

const cfg = $('Config').first().json.cfg;
const f = $('Finalize').first().json;
const row = $input.all().map(i => i.json).find(r => r.alert_key);
const send = !row || (Date.now() - Number(row.updated_ms || 0)) >= cfg.alert_cooldown_minutes * 60000;
return [{ json: { alert_key: f.system_alert.key, send, slack_text: f.system_alert.text } }];

const f = $('Finalize').first().json;
const row = $input.all().map(i => i.json).find(r => r.question_hash);
const now = Date.now();
return [{ json: {
  question_hash: f.log.question_hash,
  question_masked: f.log.question_masked,
  language: f.log.language,
  count: (row ? Number(row.count) || 0 : 0) + 1,
